```css
/* Horizontal-split slide profile.
   Two content columns (left / right) with an optional image band above the
   right column. Column ratios come from `horizontal_split.left` / `.right`.
   Selectors are `#xframe`-scoped so defaults win over shared deck styles. */
#xframe .segment[data-layout="horizontal-split"] {
  box-sizing: border-box;
  min-height: 0;
  overflow: hidden;
}

#xframe .segment[data-layout="horizontal-split"] > .layout-container {
  height: 100%;
  min-height: 0;
  gap: 0.85rem;
}

/* Content columns */
#xframe .horizontal-split-left,
#xframe .horizontal-split-right {
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  gap: 0.85rem;
  min-width: 0;
  min-height: 0;
  overflow: auto;
}

#xframe .horizontal-split-left > :is(h1, h2, h3, h4, p, ul, ol, pre, table, blockquote),
#xframe .horizontal-split-right > :is(h1, h2, h3, h4, p, ul, ol, pre, table, blockquote) {
  flex: 0 0 auto;
  max-width: 100%;
}

/* Headings — normal document hierarchy (not pitch-deck kickers). */
#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > h1 {
  margin: 0;
  max-width: none;
  color: var(--fg);
  font-size: clamp(1.85rem, 3.2vw, 2.6rem);
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > h2 {
  margin: 0;
  max-width: none;
  color: var(--fg);
  font-size: clamp(1.35rem, 2.2vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > h3 {
  margin: 0;
  max-width: none;
  color: var(--muted);
  font-size: 1.15rem;
  font-weight: 600;
  line-height: 1.35;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > p {
  margin: 0;
  max-width: 42rem;
  color: color-mix(in srgb, var(--fg) 88%, var(--muted));
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > :is(ul, ol) {
  margin: 0;
  padding-left: 1.35rem;
  max-width: 42rem;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > :is(ul, ol) > li + li {
  margin-top: 0.4rem;
}

/* Code samples fill the column and scroll instead of overflowing the slide. */
#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > pre {
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  max-height: min(55%, 22rem);
  margin: 0;
  padding: 0.95rem 1.1rem;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--code-bg, #f3f4f6);
  box-shadow: none;
  font-size: 0.92rem;
  line-height: 1.45;
  white-space: pre;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > pre code {
  padding: 0;
  background: transparent;
  color: inherit;
  font-size: inherit;
}

/* Tables use the column width instead of shrinking to content. */
#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > table {
  width: 100%;
  max-width: 100%;
  margin: 0;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: color-mix(in srgb, var(--surface-bg, var(--bg)) 88%, white);
  font-size: 0.98rem;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > table th,
#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > table td {
  padding: 0.65rem 0.85rem;
  border: 0;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > table thead th {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--fg);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

#xframe .segment[data-layout="horizontal-split"] :is(.horizontal-split-left, .horizontal-split-right) > table tbody tr:last-child > :is(th, td) {
  border-bottom: 0;
}

/* Optional image band above the right column — hide when unused. */
#xframe .horizontal-split-image {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-start;
  flex: 0 0 auto;
  gap: 0.5rem;
  min-width: 0;
  height: 5.5rem;
}

#xframe .horizontal-split-image:empty,
#xframe .horizontal-split-image:not(:has(*)) {
  display: none;
  height: 0;
  margin: 0;
  padding: 0;
}

#xframe .horizontal-split-image > :is(img, figure) {
  display: block;
  box-sizing: border-box;
  width: min(100%, 12rem);
  height: 5.5rem;
  margin: 0;
  object-fit: contain;
  object-position: right center;
}

#xframe .horizontal-split-image figure {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 0.25rem;
  overflow: hidden;
}

#xframe .horizontal-split-image figure img {
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  object-fit: contain;
  object-position: right center;
}

#xframe .horizontal-split-image figcaption {
  font-size: 0.75rem;
  line-height: 1.3;
  color: var(--muted);
  text-align: right;
}

/* Evidence media share the right region's height evenly. */
#xframe .horizontal-split-right > :is(img, figure) {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  margin: 0;
  overflow: hidden;
}

#xframe .horizontal-split-right > img {
  display: block;
  width: 100%;
  object-fit: contain;
  object-position: top center;
}

#xframe .horizontal-split-right > figure {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

#xframe .horizontal-split-right > figure > img {
  display: block;
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
  height: 0;
  margin: 0;
  object-fit: contain;
  object-position: top center;
}

#xframe .horizontal-split-right figcaption {
  flex: 0 0 auto;
  font-size: 0.8rem;
  line-height: 1.35;
  color: var(--muted);
  text-align: center;
}

#xframe .horizontal-split-footer {
  color: var(--muted);
  font-size: 0.85rem;
  padding-top: 0.35rem;
  border-top: 1px solid color-mix(in srgb, var(--border) 70%, transparent);
}

#xframe .horizontal-split-footer .region > p {
  margin: 0;
}
