```css
#xframe {
  --keynote-blue: var(--accent, #0a84ff);
  --keynote-violet: #7c5cff;
  --keynote-ink: var(--fg, #111318);
  --keynote-muted: var(--muted, #646a73);
  background:
    radial-gradient(circle at 87% 14%, color-mix(in srgb, var(--accent, #0a84ff) 15%, transparent), transparent 28%),
    radial-gradient(circle at 8% 92%, rgba(124, 92, 255, .12), transparent 30%),
    var(--surface-bg, #f5f5f7);
  color: var(--keynote-ink);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", sans-serif;
}

#xframe .segment {
  background: transparent;
}

#xframe .segment .slide-frame-main {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(19rem, .9fr);
  grid-template-rows: auto auto auto auto 1fr;
  column-gap: 3.5rem;
  row-gap: .7rem;
  align-content: center;
  padding: 2rem 4.5rem 1.25rem;
}

#xframe .segment h1 {
  grid-column: 1 / -1;
  margin: 0 0 1rem;
  max-width: 9ch;
  font-size: clamp(4.5rem, 7vw, 6.25rem);
  font-weight: 720;
  letter-spacing: -.065em;
  line-height: .88;
  background: linear-gradient(115deg, #101217 12%, #445067 52%, var(--keynote-blue) 82%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

#xframe .segment h1::before {
  content: "PRESENTATION, RECOMPILED";
  display: block;
  margin-bottom: .85rem;
  color: var(--keynote-blue);
  font-size: .72rem;
  font-weight: 750;
  letter-spacing: .2em;
  line-height: 1;
}

#xframe .segment .slide-frame-main > p:nth-of-type(1) {
  grid-column: 1;
  grid-row: 2 / span 5;
  align-self: start;
  max-width: 43rem;
  margin: 0;
  color: #343840;
  font-size: 1.12rem;
