#xframe .segment .slide-frame-main > p:nth-of-type(1)::first-line {
  color: var(--keynote-ink);
  font-size: 1.18rem;
  font-weight: 650;
  letter-spacing: -.025em;
}

#xframe .segment .slide-frame-main > p:nth-of-type(2),
#xframe .segment .slide-frame-main > p:nth-of-type(3) {
  grid-column: 2;
  margin: .1rem 0 0;
