}

#xframe .segment .slide-frame-main > p:nth-of-type(2) { grid-row: 2; }
#xframe .segment .slide-frame-main > [data-static-audience] { grid-column: 2; grid-row: 3; }
#xframe .segment .slide-frame-main > p:nth-of-type(3) { grid-row: 4; margin-top: .8rem; }

#xframe .segment audio {
  width: 100%;
  height: 2.65rem;
  border-radius: .75rem;
  filter: drop-shadow(0 .45rem 1rem rgba(25, 35, 55, .1));
}

#xframe .segment [data-static-audience][hidden] { display: none; }

.pitch-narrator {
  grid-column: 2;
  grid-row: 5;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: .8rem;
  align-self: start;
  margin: 0;
  padding: 1.1rem;
  border: 1px solid rgba(255, 255, 255, .8);
  border-radius: 1.25rem;
  background: rgba(255, 255, 255, .68);
  box-shadow: 0 1.2rem 3rem rgba(39, 49, 74, .12), inset 0 1px 0 white;
  backdrop-filter: blur(24px) saturate(140%);
}

.pitch-narrator label {
  display: grid;
  gap: .38rem;
  color: var(--keynote-muted);
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .04em;
}

.pitch-narrator label:first-child { grid-column: 1 / -1; }

.pitch-narrator .fresh-translation {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: .5rem;
  color: var(--keynote-muted);
  font-size: .72rem;
  font-weight: 600;
  letter-spacing: 0;
}

.pitch-narrator .fresh-translation input {
  width: 1rem;
  height: 1rem;
  margin: 0;
  accent-color: var(--keynote-blue);
}

.pitch-narrator select,
.pitch-narrator button {
  min-width: 0;
  border: 1px solid rgba(18, 24, 38, .1);
  border-radius: .7rem;
  padding: .64rem .72rem;
  color: var(--keynote-ink);
  background: rgba(246, 247, 249, .92);
  font: 600 .86rem/1 -apple-system, BlinkMacSystemFont, sans-serif;
  outline: none;
}

.pitch-narrator select:focus-visible,
.pitch-narrator button:focus-visible {
  box-shadow: 0 0 0 3px rgba(10, 132, 255, .24);
}

.pitch-narrator button {
  grid-column: 1 / -1;
  border: 0;
  padding: .75rem 1rem;
  color: white;
  background: linear-gradient(135deg, var(--keynote-blue), var(--keynote-violet));
  box-shadow: 0 .55rem 1.2rem rgba(52, 100, 246, .26);
  cursor: pointer;
  transition: transform .18s ease, box-shadow .18s ease;
}

.pitch-narrator button:hover {
  transform: translateY(-1px);
  box-shadow: 0 .75rem 1.45rem rgba(52, 100, 246, .32);
}

.pitch-narrator + p {
  grid-column: 2;
  min-height: 2.65rem;
  margin: 0;
  color: var(--keynote-muted);
  font-size: .82rem;
}

#xframe .segment .slide-frame-footer {
  border: 0;
  background: transparent;
  opacity: .55;
}

#xframe[data-theme="dark"] {
  --keynote-ink: #f5f5f7;
  --keynote-muted: #a7adb8;
  background:
    radial-gradient(circle at 87% 14%, rgba(10, 132, 255, .22), transparent 30%),
