}

#xframe[data-theme="dark"] .segment .slide-frame-main > p:nth-of-type(1) { color: #c1c6cf; }
#xframe[data-theme="dark"] .pitch-narrator {
  border-color: rgba(255, 255, 255, .09);
  background: rgba(24, 27, 34, .72);
  box-shadow: 0 1.2rem 3rem rgba(0, 0, 0, .32), inset 0 1px 0 rgba(255,255,255,.08);
}
#xframe[data-theme="dark"] .pitch-narrator select {
  border-color: rgba(255,255,255,.1);
  color: #f5f5f7;
  background: #242832;
}
